package vn.svframe.mythiclibfabric.runtime.script;
import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;
public final class TriggerRuntime {public record Context(UUID player,String trigger,Map<String,Object> data){}public interface Handler{boolean handle(Context context);}private record Entry(String trigger,int priority,Handler handler){}private final List<Entry> entries=new CopyOnWriteArrayList<>();public void register(String trigger,int priority,Handler h){entries.add(new Entry(norm(trigger),priority,h));entries.sort(Comparator.comparingInt(Entry::priority).reversed());}public boolean fire(Context c){boolean handled=false;for(Entry e:entries)if(e.trigger().equals(norm(c.trigger())))handled|=e.handler().handle(c);return handled;}private static String norm(String s){return s.trim().toLowerCase(Locale.ROOT);}}
